Given an array arr[] of integers, select k elements such that the minimum absolute difference between any two of the selected elements is as large as possible.Out of all possible combinations of k elements from the array, choose the one where the smallest absolute difference between any pair of selected elements is the maximum possible across all combinations.Return this maximum possible value of the minimum absolute difference.Examples:Input: arr = [2, 6, 2, 5], k = 3Output: 1Explanation: One possible selection is [2, 5, 6], where the minimum difference between any two is 1. No selection of 3 elements can give a higher minimum gap.Input: arr = [1, 4, 9, 0, 2, 13, 3], k = 4Output: 4Explanation: Selecting [0, 4, 9, 13] gives minimum pairwise difference 4, which is the largest possible under the given constraints.Try It YourselfTable of Content[Approach] Top-Down DP with 3D Memoization[Expected Approach] Binary Search on Answer with Greedy Feasibility Check [Approach] Top-Down DP with 3D MemoizationThe idea is to use top-down DP with memoization to explore all combinations of selecting k elements from the sorted array.Sorting helps ensure that differences are non-negative and simplifies computing abs(arr[i] - arr[prev]) as just arr[i] - arr[prev].The DP state dp[i][remk][prev] stores the maximum achievable minimum absolute difference when starting from index i, having selected remk elements so far, and the last selected index as prev. At each step, we either skip the current element or take it and update the minimum difference.We return the maximum of the two choices. This is a DP problem due to optimal substructure and overlapping subproblems, which we avoid recomputing using memoization.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

// returns the maximum achievable minimum 
// absolute difference
int helper(int i, int remk, int prev,
                vector<int>& arr, int k,
                vector<vector<vector<int>>>& memo) {

    // no more comparisons needed, neutral value
    if (remk == k)
        return INT_MAX; 

    // invalid, ran out of elements
    if (i == arr.size())
        return -1;

    if (memo[i][remk][prev + 1] != -2)
        return memo[i][remk][prev + 1];

    // skip current element
    int skip = 
        helper(i + 1, remk, prev, arr, k, memo);

    // take current element
    int diff = 
        (prev == -1) ? INT_MAX : abs(arr[i] - arr[prev]);
    int next = helper(i + 1, remk + 1, i, arr, k, memo);
    int take = (next == -1) ? -1 : min(diff, next);

    // store and return the max of both choices
    return memo[i][remk][prev + 1] = max(skip, take);
}

int maxMinDiff(vector<int>& arr, int k) {

    sort(arr.begin(), arr.end());
    int n = arr.size();

    // initialize 3D memo with -2 (uncomputed)
    vector<vector<vector<int>>> memo(n + 1,
        vector<vector<int>>(k + 1, vector<int>(n + 1, -2)));

    return helper(0, 0, -1, arr, k, memo);
}

int main() {

    vector<int> arr = {1, 4, 9, 0, 2, 13, 3};
    int k = 4;
    cout << maxMinDiff(arr, k) << endl; 

    return 0;
}


