    using System;

class GfG {

    // returns the maximum achievable minimum 
    // absolute difference
    static int helper(int i, int remk, int prev,
                      int[] arr, int k,
                      int[,,] memo) {

        // no more comparisons needed, neutral value
        if (remk == k)
            return int.MaxValue;

