        Array.Sort(arr);
        int n = arr.Length;

        // initialize 3D memo with -2 (uncomputed)
        int[,,] memo = new int[n + 1, k + 1, n + 1];
        for (int i = 0; i <= n; i++)
            for (int j = 0; j <= k; j++)
                for (int l = 0; l <= n; l++)
                    memo[i, j, l] = -2;

        return helper(0, 0, -1, arr, k, memo);
    }

