Time Complexity: O(n × k × n), we use a 3D DP with states defined by i (index), remk (picked count), and prev (last picked index). Each state is computed once and does constant work, giving a total of O(n × k × n) states.Auxiliary Space: O(n × n × k)[Expected Approach] Binary Search on Answer with Greedy Feasibility Check We want to select k elements such that the minimum absolute difference between any two selected elements is maximized.To find the best such minimum difference, we binary search on the answer space (possible min differences).For each candidate difference mid, we greedily try to pick k elements such that the absolute difference between every consecutive pick is at least mid.Sorting the array first is essential because it ensures that once we pick a number, we only need to check increasing values for valid selections.Why the Problem is Monotonic (in Binary Search + Greedy):This problem exhibits monotonic behavior in terms of the minimum difference (mid) we are trying to maximize — which makes it a perfect candidate for binary search on the answer.If a particular minimum difference d is possible (i.e., we can select k elements with at least d absolute gap between each),Then all smaller values of d (d - 1, d - 2, ..., 0) are also guaranteed to be possible.Conversely, if d is not possible, then all larger values of d (d + 1, d + 2, ...) will also be impossible.
            C++

    #include <iostream>
#include <vector>
#include <algorithm>
using namespace std;

// checks if it's possible to pick k elements 
// with at least 'mid' difference
bool isPossible(vector<int>& arr, int k, int mid){
    int count = 1;
    int last = arr[0];

    for (int i = 1; i < arr.size(); i++) {
        if (arr[i] - last >= mid) {
            count++;
            last = arr[i];
        }
        if (count == k)
            return true;
    }

    return false;
}

int maxMinDiff(vector<int>& arr, int k){
    // sort the array
    sort(arr.begin(), arr.end());

    // define binary search range
    int low = 0;
    int high = arr.back() - arr.front();
    int answer = 0;

    // binary search to find max valid min-diff
    while (low <= high) {
        int mid = (low + high) / 2;

        if (isPossible(arr, k, mid)) {
            answer = mid;
            low = mid + 1;
        } 
        else {
            high = mid - 1;
        }
    }

    // return the maximum feasible 
    // minimum difference
    return answer;
}

int main() {

    vector<int> arr = {1, 4, 9, 0, 2, 13, 3};
    int k = 4;
    cout << maxMinDiff(arr, k) << endl;

    return 0;
}


